#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <errno.h>
#include <ctype.h>

#define MAX_PATH_LEN 256
#define MAX_FILE_SIZE (10 * 1024 * 1024)
#define INDEX_DIR "/var/lib/searchidx/data/"
#define QUARANTINE_DIR "/var/lib/searchidx/quarantine/"

typedef struct {
    char filename[MAX_PATH_LEN];
    char content_type[64];
    size_t file_size;
    unsigned char magic_bytes[8];
} upload_metadata_t;

static const char *ALLOWED_EXTENSIONS[] = {
    ".txt", ".csv", ".json", ".xml", ".log", NULL
};

static const unsigned char MAGIC_ELF[] = {0x7f, 0x45, 0x4c, 0x46};
static const unsigned char MAGIC_PE[]  = {0x4d, 0x5a};
static const unsigned char MAGIC_MACH[] = {0xfe, 0xed, 0xfa, 0xce};

int validate_extension(const char *filename) {
    const char *dot = strrchr(filename, '.');
    if (!dot) return 0;
    for (int i = 0; ALLOWED_EXTENSIONS[i] != NULL; i++) {
        if (strcasecmp(dot, ALLOWED_EXTENSIONS[i]) == 0)
            return 1;
    }
    return 0;
}

int validate_filename_chars(const char *filename) {
    for (const char *p = filename; *p; p++) {
        if (*p == '/' || *p == '\\' || *p == '\0')
            return 0;
        if (*p == '.' && *(p+1) == '.')
            return 0;
    }
    return 1;
}

int is_executable_magic(const unsigned char *magic, size_t len) {
    if (len >= 4 && memcmp(magic, MAGIC_ELF, 4) == 0) return 1;
    if (len >= 2 && memcmp(magic, MAGIC_PE, 2) == 0) return 1;
    if (len >= 4 && memcmp(magic, MAGIC_MACH, 4) == 0) return 1;
    return 0;
}

int sanitize_content_for_index(const char *src_path, const char *dst_path) {
    FILE *src = fopen(src_path, "rb");
    if (!src) return -1;

    FILE *dst = fopen(dst_path, "wb");
    if (!dst) { fclose(src); return -1; }

    char buf[4096];
    size_t n;
    while ((n = fread(buf, 1, sizeof(buf), src)) > 0) {
        for (size_t i = 0; i < n; i++) {
            if (buf[i] == '\0') buf[i] = ' ';
        }
        fwrite(buf, 1, n, dst);
    }
    fclose(src);
    fclose(dst);
    return 0;
}

int compute_storage_path(const upload_metadata_t *meta, char *out, size_t out_len) {
    /* Build path: INDEX_DIR + sanitized_filename */
    size_t dir_len = strlen(INDEX_DIR);
    size_t name_len = strlen(meta->filename);

    if (dir_len + name_len >= out_len)
        return -1;

    memcpy(out, INDEX_DIR, dir_len);
    memcpy(out + dir_len, meta->filename, name_len);
    out[dir_len + name_len] = '\0';
    return 0;
}

int process_upload(const char *tmp_path, upload_metadata_t *meta) {
    /* Step 1: Validate file size */
    struct stat st;
    if (stat(tmp_path, &st) != 0) return -1;
    if (st.st_size > MAX_FILE_SIZE) {
        fprintf(stderr, "File too large: %ld\n", st.st_size);
        return -1;
    }
    meta->file_size = st.st_size;

    /* Step 2: Validate filename characters */
    if (!validate_filename_chars(meta->filename)) {
        fprintf(stderr, "Invalid filename characters\n");
        return -1;
    }

    /* Step 3: Validate extension */
    if (!validate_extension(meta->filename)) {
        fprintf(stderr, "Disallowed extension\n");
        return -1;
    }

    /* Step 4: Read magic bytes and check for executables */
    FILE *f = fopen(tmp_path, "rb");
    if (!f) return -1;
    size_t magic_read = fread(meta->magic_bytes, 1, 8, f);
    fclose(f);

    if (is_executable_magic(meta->magic_bytes, magic_read)) {
        fprintf(stderr, "Executable content detected\n");
        return -1;
    }

    /* Step 5: Compute final storage path */
    char final_path[MAX_PATH_LEN * 2];
    if (compute_storage_path(meta, final_path, sizeof(final_path)) != 0)
        return -1;

    /* Step 6: Ensure we're writing within INDEX_DIR using realpath check */
    char resolved[PATH_MAX];

    /* Create the file first so realpath can resolve it */
    int fd = open(final_path, O_WRONLY | O_CREAT | O_EXCL, 0644);
    if (fd < 0) {
        if (errno == EEXIST) {
            fprintf(stderr, "File already exists\n");
        }
        return -1;
    }
    close(fd);

    if (realpath(final_path, resolved) == NULL) {
        unlink(final_path);
        return -1;
    }

    if (strncmp(resolved, INDEX_DIR, strlen(INDEX_DIR)) != 0) {
        fprintf(stderr, "Path traversal detected\n");
        unlink(final_path);
        return -1;
    }

    /* Step 7: Sanitize and write content */
    unlink(final_path); /* Remove empty placeholder */
    if (sanitize_content_for_index(tmp_path, final_path) != 0) {
        return -1;
    }

    /* Step 8: Set restrictive permissions */
    chmod(final_path, 0444);

    printf("Indexed: %s -> %s\n", meta->filename, final_path);
    return 0;
}

int handle_upload_request(const char *raw_filename, const char *tmp_upload_path) {
    upload_metadata_t meta;
    memset(&meta, 0, sizeof(meta));

    /* Truncate filename to fit buffer - use the basename only */
    const char *base = strrchr(raw_filename, '/');
    if (base) base++; else base = raw_filename;

    size_t copy_len = strlen(base);
    if (copy_len >= MAX_PATH_LEN) copy_len = MAX_PATH_LEN - 1;
    memcpy(meta.filename, base, copy_len);
    meta.filename[copy_len] = '\0';

    return process_upload(tmp_upload_path, &meta);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <filename> <tmp_path>\n", argv[0]);
        return 1;
    }
    return handle_upload_request(argv[1], argv[2]);
}
